# Generated by the Runebase Discord bot's npm run guide:publish: don't edit.
# A section of the menu that navigation.prune leaves out is drawn from the
# section itself, which has no front matter: give it its first page's menu
# icon (scripts/player-guide/publish.mjs NAV_ICON).


def _sections(items):
    for item in items:
        if item.is_section:
            yield item
            yield from _sections(item.children)


def on_page_context(context, page, config, nav):
    for section in _sections(nav.items):
        first = section.children[0] if section.children else None
        meta = getattr(first, "meta", None) or {}
        if getattr(first, "is_index", False) and meta.get("nav_icon"):
            section.meta = {"icon": meta["icon"], "nav_icon": meta["nav_icon"]}
    return context
